impl crate::Payload for Payload {
    const TYPE_URI: &'static str = "https://trusttasks.org/spec/git-ns/bridge/job/0.4";
    const IS_PROOF_REQUIRED: bool = true;
    const IS_ISSUED_AT_REQUIRED: bool = true;
    const IS_RECIPIENT_REQUIRED: bool = true;
    const PAYLOAD_SCHEMA: Option<&'static str> = Some(
        "{\n  \"$defs\": {\n    \"BindTarget\": {\n      \"additionalProperties\": false,\n      \"description\": \"The forge owner whose control the binding admin is to prove.\",\n      \"properties\": {\n        \"forge\": {\n          \"$ref\": \"#/$defs/ForgeHost\"\n        },\n        \"owner\": {\n          \"$ref\": \"#/$defs/Segment\"\n        }\n      },\n      \"required\": [\n        \"forge\",\n        \"owner\"\n      ],\n      \"title\": \"BindTarget\",\n      \"type\": \"object\"\n    },\n    \"DesiredRole\": {\n      \"additionalProperties\": false,\n      \"properties\": {\n        \"account\": {\n          \"$ref\": \"#/$defs/ForgeAccount\",\n          \"description\": \"The subject's linked account on this namespace's forge.\"\n        },\n        \"right\": {\n          \"$ref\": \"#/$defs/Right\",\n          \"description\": \"The highest right recorded for the subject on the repository, or `git.commit.sign` recorded on its namespace — never one held only because `git.ns.admin` implies it. A namespace admin with no right of their own there is listed as `git.ns.admin`, which every forge adapter maps to no role. The forge adapter maps the right to one of its roles.\"\n        },\n        \"subject\": {\n          \"$ref\": \"#/$defs/Did\"\n        }\n      },\n      \"required\": [\n        \"subject\",\n        \"account\",\n        \"right\"\n      ],\n      \"type\": \"object\"\n    },\n    \"Did\": {\n      \"description\": \"A bare DID in the W3C DID Core syntax (§3.1): `did:`, a method name of lowercase letters and digits, `:`, and a method-specific id of colon-separated segments drawn from `A-Z a-z 0-9 . - _` and percent-encoded octets, the last segment non-empty. A DID URL is not a DID: no path, query or fragment (`/`, `?`, `#`), so a verification-method id such as `did:key:z6Mk…#z6Mk…` is refused. Compared by exact string equality — no case folding or percent-decoding. A consumer MUST still treat the value as data: the pattern keeps shell metacharacters, whitespace and quotes out of the wire form, but it does not make a DID safe to splice into a command or markup.\",\n      \"maxLength\": 2048,\n      \"pattern\": \"^did:[a-z0-9]+:(?:(?:[A-Za-z0-9._-]|%[0-9A-Fa-f]{2})*:)*(?:[A-Za-z0-9._-]|%[0-9A-Fa-f]{2})+$\",\n      \"title\": \"Did\",\n      \"type\": \"string\"\n    },\n    \"Ext\": {\n      \"additionalProperties\": true,\n      \"description\": \"Vendor-namespaced extension object per SPEC.md §4.5.1. Each immediate key MUST be a reverse-DNS namespace; structure under each namespace is opaque to the framework.\",\n      \"minProperties\": 1,\n      \"propertyNames\": {\n        \"pattern\": \"^[a-z][a-z0-9-]*(\\\\.[a-z0-9-]+)+$\"\n      },\n      \"title\": \"Ext\",\n      \"type\": \"object\"\n    },\n    \"ForgeAccount\": {\n      \"additionalProperties\": false,\n      \"description\": \"A person's account on one forge. `id` is authoritative; `login` is for display only, because logins can be renamed and re-registered.\",\n      \"properties\": {\n        \"forge\": {\n          \"$ref\": \"#/$defs/ForgeHost\"\n        },\n        \"id\": {\n          \"$ref\": \"#/$defs/ForgeId\"\n        },\n        \"login\": {\n          \"description\": \"The account's current login, as the forge reported it when last seen. Display only.\",\n          \"maxLength\": 100,\n          \"minLength\": 1,\n          \"type\": \"string\"\n        }\n      },\n      \"required\": [\n        \"forge\",\n        \"id\",\n        \"login\"\n      ],\n      \"title\": \"ForgeAccount\",\n      \"type\": \"object\"\n    },\n    \"ForgeHost\": {\n      \"description\": \"The lowercased DNS host of a forge: `github.com`, a GitHub Enterprise Server host, `codeberg.org`, or a self-hosted Forgejo instance such as `git.example.org`. No scheme, no port, no path. The host is a segment of every resource, so a right never crosses forges.\",\n      \"maxLength\": 253,\n      \"minLength\": 3,\n      \"pattern\": \"^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?(?:\\\\.[a-z0-9](?:[a-z0-9-]*[a-z0-9])?)+$\",\n      \"title\": \"ForgeHost\",\n      \"type\": \"string\"\n    },\n    \"ForgeId\": {\n      \"description\": \"An identifier the forge itself assigns — a repository id, a user or organisation id — carried as a string so a forge whose ids are not numbers needs no new version. GitHub and Forgejo ids are decimal integers written as strings (`\\\"812736451\\\"`). Unlike a name, it survives renames and transfers, which is why rights and bindings are keyed by it.\",\n      \"maxLength\": 64,\n      \"minLength\": 1,\n      \"title\": \"ForgeId\",\n      \"type\": \"string\"\n    },\n    \"JobId\": {\n      \"description\": \"The VTC's identifier for a job, unique across the VTC's jobs.\",\n      \"maxLength\": 128,\n      \"minLength\": 1,\n      \"type\": \"string\"\n    },\n    \"NamespaceId\": {\n      \"description\": \"The VTC's opaque identifier for a namespace, assigned when it is bound. Stable for the life of the binding; never reused for another binding.\",\n      \"maxLength\": 128,\n      \"minLength\": 1,\n      \"title\": \"NamespaceId\",\n      \"type\": \"string\"\n    },\n    \"RepoResource\": {\n      \"description\": \"A forge-qualified resource naming exactly one repository: `<forge-host>/<owner>/<repo>`, lowercase.\",\n      \"maxLength\": 455,\n      \"pattern\": \"^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?(?:\\\\.[a-z0-9](?:[a-z0-9-]*[a-z0-9])?)+/[a-z0-9_-][a-z0-9._-]{0,99}/[a-z0-9_-][a-z0-9._-]{0,99}$\",\n      \"title\": \"RepoResource\",\n      \"type\": \"string\"\n    },\n    \"RepoSpec\": {\n      \"additionalProperties\": false,\n      \"properties\": {\n        \"description\": {\n          \"maxLength\": 350,\n          \"type\": \"string\"\n        },\n        \"visibility\": {\n          \"$ref\": \"#/$defs/RepoVisibility\"\n        }\n      },\n      \"required\": [\n        \"visibility\"\n      ],\n      \"type\": \"object\"\n    },\n    \"RepoVisibility\": {\n      \"description\": \"Repository visibility on the forge.\",\n      \"enum\": [\n        \"public\",\n        \"private\"\n      ],\n      \"title\": \"RepoVisibility\",\n      \"type\": \"string\"\n    },\n    \"Response\": {\n      \"$anchor\": \"response\",\n      \"additionalProperties\": false,\n      \"description\": \"Whether the bridge took the job.\",\n      \"properties\": {\n        \"accepted\": {\n          \"description\": \"`true` — the job is durably queued, or was already queued or running under this `jobId`; a git-ns/bridge/result follows. `false` — the bridge already finished this `jobId`; it does not run it again, and sends its git-ns/bridge/result again.\",\n          \"type\": \"boolean\"\n        },\n        \"ext\": {\n          \"$ref\": \"#/$defs/Ext\"\n        },\n        \"jobId\": {\n          \"$ref\": \"#/$defs/JobId\"\n        },\n        \"next\": {\n          \"additionalProperties\": false,\n          \"description\": \"For `beginBind` and `beginAccountLink` when `accepted` is `true`: where the VTC sends the person.\",\n          \"properties\": {\n            \"expiresAt\": {\n              \"format\": \"date-time\",\n              \"type\": \"string\"\n            },\n            \"url\": {\n              \"format\": \"uri\",\n              \"maxLength\": 2048,\n              \"pattern\": \"^https://\",\n              \"type\": \"string\"\n            },\n            \"userCode\": {\n              \"description\": \"The device-flow code, for a forge that uses one.\",\n              \"maxLength\": 64,\n              \"minLength\": 1,\n              \"type\": \"string\"\n            }\n          },\n          \"required\": [\n            \"url\",\n            \"expiresAt\"\n          ],\n          \"type\": \"object\"\n        }\n      },\n      \"required\": [\n        \"jobId\",\n        \"accepted\"\n      ],\n      \"title\": \"Git Namespaces — Bridge Job — response payload\",\n      \"type\": \"object\"\n    },\n    \"Right\": {\n      \"description\": \"One of the five git rights. Each string is also the TRQP `action` the VTC publishes the right under in its Trust Registry, so it is carried verbatim. `git.ns.admin` and `git.repo.create` apply to a namespace resource; `git.repo.own` and `git.repo.maintain` to a repository resource; `git.commit.sign` to either.\",\n      \"enum\": [\n        \"git.ns.admin\",\n        \"git.repo.create\",\n        \"git.repo.own\",\n        \"git.repo.maintain\",\n        \"git.commit.sign\"\n      ],\n      \"title\": \"Right\",\n      \"type\": \"string\"\n    },\n    \"Segment\": {\n      \"description\": \"One lowercased owner or repository name. Forges compare these case-insensitively, so the wire form is always lowercase and a producer lowercases before sending. A leading `.` is refused, which rules out `.` and `..`.\",\n      \"maxLength\": 100,\n      \"minLength\": 1,\n      \"pattern\": \"^[a-z0-9_-][a-z0-9._-]*$\",\n      \"title\": \"Segment\",\n      \"type\": \"string\"\n    },\n    \"StepName\": {\n      \"description\": \"One step of a forge adapter's plan. Forge-neutral names: `create`, `workflow`, `keyring`, `variables`, `requiredCheck`, `roles`, `archive`. An adapter MAY add its own (`mergeStyle`, `runner`), which a VTC displays but need not understand.\",\n      \"maxLength\": 64,\n      \"minLength\": 1,\n      \"pattern\": \"^[a-z][A-Za-z0-9]*$\",\n      \"type\": \"string\"\n    }\n  },\n  \"$id\": \"https://trusttasks.org/spec/git-ns/bridge/job/0.4\",\n  \"$schema\": \"https://json-schema.org/draft/2020-12/schema\",\n  \"additionalProperties\": false,\n  \"description\": \"The VTC asks its bridge to do one piece of forge work in a namespace. The job names what to do (`kind`) and carries the desired state, never forge credentials — the bridge holds those. Which optional members a job carries is fixed by its `kind` (see the specification's kind table); a bridge refuses a job that carries a member its kind does not use, or lacks one its kind requires.\",\n  \"properties\": {\n    \"desiredRoles\": {\n      \"description\": \"The complete set of people the projection reaches on the repository, each at the one right they are projected at. The bridge converges to exactly this set among the roles it manages: it adds or changes roles to match and removes managed roles not listed. Each forge account (by `forge` and `id`) appears at most once. `projectRoles` and `createRepo` only.\",\n      \"items\": {\n        \"$ref\": \"#/$defs/DesiredRole\"\n      },\n      \"type\": \"array\",\n      \"uniqueItems\": true\n    },\n    \"ext\": {\n      \"$ref\": \"#/$defs/Ext\"\n    },\n    \"jobId\": {\n      \"$ref\": \"#/$defs/JobId\",\n      \"description\": \"The VTC's identifier for this job. The bridge reports on it with git-ns/bridge/result.\"\n    },\n    \"kind\": {\n      \"description\": \"What to do. `projectRoles` — converge forge roles to `desiredRoles`, and remove whatever role each of `removeAccounts` holds on `repo`. `createRepo` — create `repo`, run the bootstrap plan, and project `desiredRoles`. `bootstrap` — run the bootstrap plan, or the listed `steps` of it, on an existing `repo`. `archive` — archive `repo`. `inspect` — compare the forge with the projection for `repo`, or for the whole namespace. `beginBind` — start the proof that the binding admin controls `target`. `beginAccountLink` — start linking `subject`'s account on this namespace's forge.\",\n      \"enum\": [\n        \"projectRoles\",\n        \"createRepo\",\n        \"bootstrap\",\n        \"archive\",\n        \"inspect\",\n        \"beginBind\",\n        \"beginAccountLink\"\n      ],\n      \"type\": \"string\"\n    },\n    \"namespace\": {\n      \"$ref\": \"#/$defs/NamespaceId\",\n      \"description\": \"The namespace the job acts in. It also selects the bridge's forge credentials for it.\"\n    },\n    \"removeAccounts\": {\n      \"description\": \"Accounts whose direct role on `repo` the bridge removes, whatever that role is — including a role the bridge does not manage and would otherwise only report as drift. Matched by `forge` and `id`; `login` is display only. No account listed here may also appear in `desiredRoles`, except at `git.ns.admin`. `projectRoles` only.\",\n      \"items\": {\n        \"$ref\": \"#/$defs/ForgeAccount\"\n      },\n      \"minItems\": 1,\n      \"type\": \"array\",\n      \"uniqueItems\": true\n    },\n    \"repo\": {\n      \"$ref\": \"#/$defs/RepoResource\",\n      \"description\": \"The repository. Required for `projectRoles`, `createRepo`, `bootstrap` and `archive`: there is no namespace-level `projectRoles`, because no right projects to an organisation's own roles. For `inspect`, absent means a sweep of every repository in the namespace.\"\n    },\n    \"spec\": {\n      \"$ref\": \"#/$defs/RepoSpec\",\n      \"description\": \"How to create the repository. `createRepo` only.\"\n    },\n    \"steps\": {\n      \"description\": \"Run only these steps of the adapter's bootstrap plan, in the plan's order. Absent: the whole plan. `bootstrap` only.\",\n      \"items\": {\n        \"$ref\": \"#/$defs/StepName\"\n      },\n      \"minItems\": 1,\n      \"type\": \"array\",\n      \"uniqueItems\": true\n    },\n    \"subject\": {\n      \"$ref\": \"#/$defs/Did\",\n      \"description\": \"The member whose forge account is being linked. `beginAccountLink` only.\"\n    },\n    \"target\": {\n      \"$ref\": \"#/$defs/BindTarget\",\n      \"description\": \"`beginBind` only.\"\n    }\n  },\n  \"required\": [\n    \"jobId\",\n    \"namespace\",\n    \"kind\"\n  ],\n  \"title\": \"Git Namespaces — Bridge Job — payload\",\n  \"type\": \"object\"\n}\n",
    );
}
